// GeoZone An airspace of defined dimensions, above the land areas or territorial waters of a State, within which a particular restriction or condition for UAS flights applies.
type GeoZone struct {
	// AdditionalProperties Indicates that exemptions from the national or European regulations are allowed in the UAS Zone, that will be detailed via the "message" property.
	AdditionalProperties *map[string]interface{} `json:"additional_properties,omitempty"`

	// Country The State that has the authority to declare the zone.
	// Note - There will be no Zone belonging to two States. Not necessary to code the information that two zones are "in neighboring States" or "related".
	Country GeoZone_Country `json:"country"`

	// Identifier A string of characters that uniquely identifies the UAS Zone within the State/Territory identified by the country attribute.
	// Note - The UAS Zone is uniquely identified worldwide by the combination of the country and the identifier attributes
	Identifier GeoZone_Identifier `json:"identifier"`

	// Message A message to be displayed to the user of the zone, typically on the RPS for the Remote Pilot, to make him/her aware about specific information associated with the zone (typically when it is not only a restriction to fly in the zone, thus not only an alert or an automatic limitation, for example : “image capture prohibited in this zone”, “frequent strong winds in this zone”, “no landing or take-off in this zone”). This message is also used to indicate exemptions from regulation in a zone (see below). Several information can be grouped in a message, separated by a “/”.
	Message *GeoZone_Message `json:"message,omitempty"`

	// Name A free text name by which the zone may be known by the public or by the UAS community.
	Name *GeoZone_Name `json:"name,omitempty"`

	// OtherReasonInfo A free text description of the reason that led to the establishment of the zone, when not covered by a pre-defined coded value.
	OtherReasonInfo *string `json:"other_reason_info,omitempty"`

	// Reason A coded indication for the reason that led to the establishment of the zone.
	Reason *[]CodeZoneReasonType `json:"reason,omitempty"`

	// Region Where applicable, identifies a region inside a State where the UAS Zone is located.
	// Note 1) identified with a digit between 0-65535 (16 bit), corresponding to a list of regions pre-defined for each State.
	// Note 2) this attribute is intended to facilitate extracting sub-sets of data, for specific regions
	Region *int32 `json:"region,omitempty"`

	// RegulationExemption This is an extension point. It allows adding additional attributes of national interest through this element.
	RegulationExemption *GeoZone_RegulationExemption `json:"regulation_exemption,omitempty"`

	// Restriction An indication if flying in the zone is conditional, forbidden or unrestricted.
	Restriction GeoZone_Restriction `json:"restriction"`

	// RestrictionConditions An indication of the conditions under which the zone can be used
	RestrictionConditions *[]ConditionExpressionType `json:"restriction_conditions,omitempty"`

	// Type An indication whether the Zone is provided with its common definition or with a customised definition, for a particular user.
	Type GeoZone_Type `json:"type"`

	// USpaceClass A code that identifies the category or class of the zone applying a "USpace concept".
	// Note: Two (draft) classifications exist, one from Eurocontrol and one from CORUS. Therefore, two instances of this attribute are expected, one from each sub-list. This might be later replaced with separate attributes and separate lists of values.
	USpaceClass   *GeoZone_USpaceClass `json:"u_space_class,omitempty"`
	ZoneAuthority []Authority          `json:"zone_authority"`
}

