// OperationalIntentReference The high-level information of a planned or active operational intent with the URL of a USS to query for details.  Note: 'ovn' is returned ONLY to the USS that created the operational intent but NEVER to other USS instances.
type OperationalIntentReference struct {
	// Id Identifier for an Entity communicated through the DSS.  Formatted as a UUIDv4.
	//
	// Example: 2f8343be-6482-4d1b-a474-16847e01af1e
	Id EntityID `json:"id"`

	// Manager Created by the DSS based on creating client's ID (via access token).  Used internal to the DSS for restricting mutation and deletion operations to manager.  Used by USSs to reject operational intent update notifications originating from a USS that does not manage the operational intent.
	//
	// Example: uss1
	Manager string `json:"manager"`

	// Ovn Opaque version number of this operational intent.  Populated only when the OperationalIntentReference is managed by the USS retrieving or providing it.  Not populated when the OperationalIntentReference is not managed by the USS retrieving or providing it (instead, the USS must obtain the OVN from the details retrieved from the managing USS).
	Ovn *OperationalIntentReference_Ovn `json:"ovn,omitempty"`

	// State State of an operational intent.
	// 'Accepted': Operational intent is created and shared, but not yet in use; see standard text for more details.
	// The create or update request for this operational intent reference must include a Key containing all OVNs for all relevant Entities.
	// 'Activated': Operational intent is in active use; see standard text for more details.
	// The create or update request for this operational intent reference must include a Key containing all OVNs for all relevant Entities.
	// 'Nonconforming': UA is temporarily outside its volumes, but the situation is expected to be recoverable; see standard text for more details.
	// In this state, the `/uss/v1/operational_intents/{entityid}/telemetry` USS-USS endpoint should respond, if available, to queries from USS peers.  The create or update request for this operational intent may omit a Key in this case because the operational intent is being adjusted as flown and cannot necessarily deconflict.
	// 'Contingent': UA is considered unrecoverably unable to conform with its coordinate operational intent; see standard text for more details.
	// This state must transition to Ended.  In this state, the `/uss/v1/operational_intents/{entityid}/telemetry` USS-USS endpoint should respond, if available, to queries from USS peers.  The create or update request for this operational intent may omit a Key in this case because the operational intent is being adjusted as flown and cannot necessarily deconflict.
	State OperationalIntentState `json:"state"`

	// SubscriptionId The ID of the subscription that is ensuring the operational intent manager receives relevant airspace updates.
	SubscriptionId OperationalIntentReference_SubscriptionId `json:"subscription_id"`

	// TimeEnd End time of operational intent.
	TimeEnd OperationalIntentReference_TimeEnd `json:"time_end"`

	// TimeStart Beginning time of operational intent.
	TimeStart OperationalIntentReference_TimeStart `json:"time_start"`

	// UssAvailability A USS is presumed to be in the Unknown state absent indication otherwise by a USS with availability arbitration scope.  Upon determination via availability arbitration, a USS is Down when it does not respond appropriately, and a Down USS may not perform the following operations in the DSS:
	// * Create an operational intent in the Accepted or Activated states
	// * Modify an operational intent whose new or unchanged state is Accepted or Activated
	// * Delete an operational intent
	// A USS in the Unknown state possesses all the capabilities, within the DSS, of a USS in the Normal state.
	UssAvailability UssAvailabilityState `json:"uss_availability"`

	// UssBaseUrl The base URL of a USS implementation that implements the parts of the USS-USS API necessary for providing the details of this operational intent, and telemetry during non-conformance or contingency, if applicable.
	UssBaseUrl OperationalIntentUssBaseURL `json:"uss_base_url"`

	// Version Numeric version of this entity which increments upon each change in the entity, regardless of whether any field of the entity changes.  A USS with the details of this entity when it was at a particular version does not need to retrieve the details again until the version changes.
	//
	// Example: 1
	Version EntityVersion `json:"version"`
}

// OperationalIntentReference_Ovn Opaque version number of this operational intent.  Populated only when the OperationalIntentReference is managed by the USS retrieving or providing it.  Not populated when the OperationalIntentReference is not managed by the USS retrieving or providing it (instead, the USS must obtain the OVN from the details retrieved from the managing USS).
type OperationalIntentReference_Ovn = EntityOVN

// OperationalIntentReference_SubscriptionId The ID of the subscription that is ensuring the operational intent manager receives relevant airspace updates.
type OperationalIntentReference_SubscriptionId = SubscriptionID

// OperationalIntentReference_TimeEnd End time of operational intent.
type OperationalIntentReference_TimeEnd = Time

// OperationalIntentReference_TimeStart Beginning time of operational intent.
type OperationalIntentReference_TimeStart = Time

// OperationalIntentState State of an operational intent.
// 'Accepted': Operational intent is created and shared, but not yet in use; see standard text for more details.
// The create or update request for this operational intent reference must include a Key containing all OVNs for all relevant Entities.
// 'Activated': Operational intent is in active use; see standard text for more details.
// The create or update request for this operational intent reference must include a Key containing all OVNs for all relevant Entities.
// 'Nonconforming': UA is temporarily outside its volumes, but the situation is expected to be recoverable; see standard text for more details.
// In this state, the `/uss/v1/operational_intents/{entityid}/telemetry` USS-USS endpoint should respond, if available, to queries from USS peers.  The create or update request for this operational intent may omit a Key in this case because the operational intent is being adjusted as flown and cannot necessarily deconflict.
// 'Contingent': UA is considered unrecoverably unable to conform with its coordinate operational intent; see standard text for more details.
// This state must transition to Ended.  In this state, the `/uss/v1/operational_intents/{entityid}/telemetry` USS-USS endpoint should respond, if available, to queries from USS peers.  The create or update request for this operational intent may omit a Key in this case because the operational intent is being adjusted as flown and cannot necessarily deconflict.
type OperationalIntentState string

// OperationalIntentUssBaseURL The base URL of a USS implementation that implements the parts of the USS-USS API necessary for providing the details of this operational intent, and telemetry during non-conformance or contingency, if applicable.
